export const SUBJECT_FLASHCARDS_CSP_SCENARIO: SubjectFlashcard[] = [
  { id: "csp-scenario-001", deck: "csp-scenario", category: "AP CSP · 情境题", front: "a←[3,7,2,9]\nAPPEND(a,5)\nINSERT(a,2,6)\nREMOVE(a,4)\n列表下标从 1 开始，执行后 a 的内容是？\nA. 结果变为 [3,6,7,2,9,5]\nB. 结果变为 [3,6,7,2,5]\nC. 结果变为 [3,6,7,9,5]\nD. 结果变为 [3,6,7,2,9]", back: "答案：C\n简析：一句话解析：A 误把 REMOVE 当成按值删除（列表里没有 4，于是什么都没删），B 在插入后的列表里把数值 9 当成要删除的元素（混淆下标与元素值），D 误以为 REMOVE 删除的是最后一个元素。\n\n正确选项：结果变为 [3,6,7,9,5]", source: "ai-mcq", verified: true },
  { id: "csp-scenario-002", deck: "csp-scenario", category: "AP CSP · 情境题", front: "t←0\nFOR EACH x IN [2,5,3,80]\nIF (x MOD 2) = 0\nt←t+x\nELSE\nt←t-x\n执行后 t 的值是？\nA. t 等于 74\nB. t 等于 -74\nC. t 等于 82\nD. t 等于 90", back: "答案：A\n简析：一句话解析：B 把条件写反（偶数减、奇数加）得 -74，C 忽略了 ELSE 分支只累加偶数得 82，D 完全忽略条件把 4 个元素全部相加得 90。\n\n正确选项：t 等于 74", source: "ai-mcq", verified: true },
  { id: "csp-scenario-003", deck: "csp-scenario", category: "AP CSP · 情境题", front: "某班 11 名学生每日屏幕使用时间（小时）排序后为 1、2、2、3、3、3、4、4、5、6、48，其中 48 是录入错误。若把 48 改成 4，下列哪项正确？\nA. 中位数与平均值都不变，因为数据个数没变\nB. 中位数与平均值都降低，其中中位数降得更多\nC. 中位数降低约 2，平均值降低约 4 小时\nD. 中位数保持不变，平均值降低约 4 小时", back: "答案：D\n简析：一句话解析：A 只看到数据个数没变就认为两个统计量都不变，B 误以为中位数比平均值更容易被极端值拉动，C 误以为中位数会变化（48 改成 4 后中位数仍是 3）。\n\n正确选项：中位数保持不变，平均值降低约 4 小时", source: "ai-mcq", verified: true },
  { id: "csp-scenario-004", deck: "csp-scenario", category: "AP CSP · 情境题", front: "某校想估计全校 1200 名学生的平均睡眠时长。调查者在上学日 7:30 只询问最早到校的 100 名学生，并且只通过校园 App 推送问卷。关于这个样本，哪项正确？\nA. 样本只有 100 人，把人数扩大到 300 人就能消除偏差\nB. 样本不具代表性，早到且装 App 的学生睡眠可能更少\nC. 这是在学生中随机抽样，因此结果可以推断因果关系\nD. 问卷通过校内 App 收集并加密传输，所以数据较为客观可靠", back: "答案：B\n简析：一句话解析：A 以为样本量能消除偏差，C 把方便样本误认成随机抽样并进一步推断因果，D 把传输加密误当成数据客观可靠。\n\n正确选项：样本不具代表性，早到且装 App 的学生睡眠可能更少", source: "ai-mcq", verified: true },
  { id: "csp-scenario-005", deck: "csp-scenario", category: "AP CSP · 情境题", front: "g←[58,72,91,45,88]\nt←0\nc←0\nFOR EACH x IN g\nIF x ≥ 60\nt←t+x\nc←c+1\nDISPLAY(t/c)\n程序输出约 83.7，这个输出表示？\nA. 全部 5 名学生分数的算术平均值\nB. 达到 60 分那 3 名学生的分数总和\nC. 达到 60 分那 3 名学生的平均分\nD. 达到 60 分学生总分占全班总分的比例", back: "答案：C\n简析：一句话解析：A 忽略了 IF 条件（全班平均约为 70.8），B 忘掉最后一次除法只看累加结果 251，D 把分子分母看成及格总分与全班总分（比值约 70.9%）。\n\n正确选项：达到 60 分那 3 名学生的平均分", source: "ai-mcq", verified: true },
  { id: "csp-scenario-006", deck: "csp-scenario", category: "AP CSP · 情境题", front: "某图像为 50×100 像素，每个像素的亮度用 4 位表示，未压缩存储。关于该图像，哪项正确？\nA. 需要 2500 字节，亮度共有 16 种取值\nB. 需要 20000 字节，亮度共有 16 种取值\nC. 需要 2500 字节，亮度共有 4 种取值\nD. 需要 5000 字节，亮度共有 256 种取值", back: "答案：A\n简析：一句话解析：B 把 4 位当成 4 字节算出 20000 字节，C 把位深直接当成取值个数（16 种误写成 4 种），D 忽略位深按每像素 1 字节计算并错用 8 位的色彩数。\n\n正确选项：需要 2500 字节，亮度共有 16 种取值", source: "ai-mcq", verified: true },
  { id: "csp-scenario-007", deck: "csp-scenario", category: "AP CSP · 情境题", front: "远程手术系统要求操作指令的往返延迟低于 50 毫秒，同时约需 20 Mbps 带宽传回视频。运营商把带宽从 20 Mbps 提升到 100 Mbps，两地之间的往返延迟没有变化。哪项正确？\nA. 带宽提高后延迟会随之降低，操作手感明显变好\nB. 带宽提高意味着不再发生丢包，两端传输必然可靠\nC. 延迟由两地距离决定，任何技术手段都无法降低它\nD. 视频回传画面可以更清晰，但操作手感不会改善", back: "答案：D\n简析：一句话解析：A 是「带宽大所以延迟低」的典型误解，B 把带宽与可靠性混为一谈（带宽不消除丢包），C 忽略了路由优化、边缘节点等确实能降低延迟的手段。\n\n正确选项：视频回传画面可以更清晰，但操作手感不会改善", source: "ai-mcq", verified: true },
  { id: "csp-scenario-008", deck: "csp-scenario", category: "AP CSP · 情境题", front: "一条消息被拆成 5 个包经分组交换网络发送，第 3 个包在途中丢失，接收方收到了其余 4 个包。哪项正确？\nA. 只要网络中存在冗余路径，任何包都不会丢失，因此接收方无需请求重传\nB. 丢失的包可以经另一条路径重传，接收方按序号重组成原消息\nC. 包必须按发送顺序沿同一条路径到达，否则整条消息必须作废\nD. 发送方必须把全部 5 个包重新发送一次，才能恢复整条消息", back: "答案：B\n简析：一句话解析：A 把冗余路径误当成永不丢包，C 误以为包必须走同一路径且严格有序到达，D 误以为丢一个包就要重发全部数据。\n\n正确选项：丢失的包可以经另一条路径重传，接收方按序号重组成原消息", source: "ai-mcq", verified: true },
  { id: "csp-scenario-009", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生在浏览器输入 school.example.edu 并成功打开页面。关于这次访问，哪项正确？\nA. 浏览器直接用域名与服务器通信，IP 地址只在解析失败时使用\nB. TCP/IP 负责把网页渲染成图像，HTTP 负责传输网页的比特\nC. 域名先被 DNS 解析成 IP 地址，浏览器再据此请求网页内容\nD. 一个域名只能对应一个 IP 地址，所以每次访问都连到同一台服务器", back: "答案：C\n简析：一句话解析：A 以为可以直接用域名通信，B 把 TCP/IP 与 HTTP 的职责对调还混入了渲染，D 误以为一个域名只能对应一个 IP（忽略了负载均衡与多台服务器）。\n\n正确选项：域名先被 DNS 解析成 IP 地址，浏览器再据此请求网页内容", source: "ai-mcq", verified: true },
  { id: "csp-scenario-010", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生要把 120 MB 的作业上传到服务器，上行带宽为 10 Mbps，忽略协议开销（1 字节 = 8 位）。上传大约需要多久？\nA. 大约 96 秒\nB. 大约 12 秒\nC. 大约 960 秒\nD. 大约 9600 秒", back: "答案：A\n简析：一句话解析：B 忽略字节与位的换算直接用 120÷10，C 换算后忘记除以带宽只留下 960，D 把除法写成乘法得到 960×10。\n\n正确选项：大约 96 秒", source: "ai-mcq", verified: true },
  { id: "csp-scenario-011", deck: "csp-scenario", category: "AP CSP · 情境题", front: "医院把病历同时存放在 3 个数据中心，其中 1 个因停电宕机时系统仍能访问数据，但每年的维护费用明显上升。哪项正确？\nA. 这体现了加密，因为数据分散存放后别人无法读取其中的内容\nB. 多份副本共享同一份数据，所以总存储与维护成本不会上升\nC. 这体现容错，而且只要有多份副本，数据就不会被错误修改\nD. 这体现容错，单个数据中心故障时仍可访问，只是成本上升", back: "答案：D\n简析：一句话解析：A 把冗余误当成加密，B 误以为副本不占额外存储与成本（副本反而增加总开销），C 错在以为冗余能保证数据内容正确。\n\n正确选项：这体现容错，单个数据中心故障时仍可访问，只是成本上升", source: "ai-mcq", verified: true },
  { id: "csp-scenario-012", deck: "csp-scenario", category: "AP CSP · 情境题", front: "某校园 App 收集以下数据：学号、出生日期、每天步数总计、电子邮箱、每天上课的教室编号。哪项正确？\nA. 只有姓名算个人可识别信息，学号和邮箱都只是普通编号\nB. 学号属于个人可识别信息，教室编号组合也可能定位到个人\nC. 只要不收集姓名，这些数据就不再属于个人信息，可对外公开\nD. 步数也属于个人可识别信息，因为它以数字形式存储", back: "答案：B\n简析：一句话解析：A 把 PII 等同于姓名，C 以为去掉姓名就等于去标识化，D 把数据格式（数字）当成敏感程度的判断依据。\n\n正确选项：学号属于个人可识别信息，教室编号组合也可能定位到个人", source: "ai-mcq", verified: true },
  { id: "csp-scenario-013", deck: "csp-scenario", category: "AP CSP · 情境题", front: "某网站用 HTTPS 传输登录信息，服务器只保存「密码 + 随机盐」的哈希值，登录时比较哈希值。哪项正确？\nA. 哈希是一种可逆加密，服务器能用密钥把哈希还原成原密码\nB. HTTPS 能保证数据库里的密码不被攻击者读取，所以不必再做哈希\nC. 传输过程由 HTTPS 保护，数据库泄露后哈希也难以还原密码\nD. 加盐的作用是让同一密码每次都生成相同的哈希值，便于比较", back: "答案：C\n简析：一句话解析：A 把不可逆的哈希当成可逆加密，B 把传输加密的保护范围扩大到服务器数据库，D 把加盐误解成让哈希保持固定（加盐恰恰使每次结果不同）。\n\n正确选项：传输过程由 HTTPS 保护，数据库泄露后哈希也难以还原密码", source: "ai-mcq", verified: true },
  { id: "csp-scenario-014", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生用「密码 + 手机验证码」登录校园系统，系统还按角色限制他只能查看自己的成绩。哪项正确？\nA. 密码与手机验证码用于认证，限制查看范围属于授权\nB. 验证码属于授权，因为它决定了你可以看到哪些页面\nC. 两者都属于加密措施，因为它们都保护了数据的机密性\nD. 有了双因素认证就能保证账号不被破解，因此不必再要求强密码", back: "答案：A\n简析：一句话解析：B 把认证手段误当成授权，C 把认证误当成加密（加密不判断身份），D 夸大双因素认证的作用并据此放弃强密码。\n\n正确选项：密码与手机验证码用于认证，限制查看范围属于授权", source: "ai-mcq", verified: true },
  { id: "csp-scenario-015", deck: "csp-scenario", category: "AP CSP · 情境题", front: "某团队用过去 5 年的记录训练「预测学生是否需要补习」的模型。由于低收入学生过去较少获得补习，模型对这类学生的预测偏低。哪项正确？\nA. 只要把家庭收入这一字段删掉，模型的输出就不会再有偏差\nB. 偏差说明数据量不足，把记录增加到 10 倍即可消除\nC. 模型只是数学计算，因此不会产生任何实际社会影响\nD. 偏差来自历史数据的形成方式，删掉收入字段也无法消除", back: "答案：D\n简析：一句话解析：A 误以为去掉敏感字段就消除了偏差，B 把偏差当成样本量不足，C 忽略了算法结论对真实人群的影响。\n\n正确选项：偏差来自历史数据的形成方式，删掉收入字段也无法消除", source: "ai-mcq", verified: true },
  { id: "csp-scenario-016", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学校计划把学生出勤数据共享给一家公司，用于「旷课提醒」服务，公司会长期保留原始数据并用于改进自己的模型。哪项最需要关注？\nA. 数据共享的主要风险是传输变慢，可以与公司协商提高带宽\nB. 学生的数据被长期保留并二次使用，本人难以撤回或知情\nC. 学校与公司签了合同之后，学生就不再是利益相关者\nD. 出勤记录不属于个人信息，因此共享无需告知学生或征得同意", back: "答案：B\n简析：一句话解析：A 把隐私风险误当成带宽问题，C 以为签了合同学生就不再是利益相关者，D 误判出勤数据不属于个人信息而免去告知义务。\n\n正确选项：学生的数据被长期保留并二次使用，本人难以撤回或知情", source: "ai-mcq", verified: true },
  { id: "csp-scenario-017", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生对一个未排序的 1000 项列表直接使用二分查找来查找某个值。哪项正确？\nA. 二分查找对任何列表都有效，只要长度是 2 的幂\nB. 二分查找的比较次数与列表长度无关，总能在一步内找到\nC. 二分查找属于启发式方法，速度快但不能保证找到目标\nD. 二分查找要求列表已排序，否则查找结果可能不正确", back: "答案：D\n简析：一句话解析：A 用长度是否为 2 的幂代替了有序性这个前提，B 误以为比较次数与长度无关且能一步命中，C 把确定性的二分查找误当成启发式方法。\n\n正确选项：二分查找要求列表已排序，否则查找结果可能不正确", source: "ai-mcq", verified: true },
  { id: "csp-scenario-018", deck: "csp-scenario", category: "AP CSP · 情境题", front: "某团队模拟食堂排队时间，假设每名学生点餐恰好用 30 秒，并且没有考虑课间高峰时学生同时到达。哪项正确？\nA. 模拟结果仅在假设成立时有效，忽略高峰则会使预测偏乐观\nB. 模拟使用了随机数，因此不需要验证，随机性会自动消除误差\nC. 只要增加模拟运行的次数，任何错误的假设都会被自动纠正\nD. 模拟是对真实系统的实验，其结论就是真实世界的因果结论", back: "答案：A\n简析：一句话解析：B 把随机性当成免检理由，C 以为多次运行能自动纠正假设错误，D 把模拟输出直接当成真实世界的因果结论。\n\n正确选项：模拟结果仅在假设成立时有效，忽略高峰则会使预测偏乐观", source: "ai-mcq", verified: true },
  { id: "csp-scenario-019", deck: "csp-scenario", category: "AP CSP · 情境题", front: "关于「判断任意程序 P 在输入 I 上是否会停止」这个问题，哪项正确？\nA. 该问题不可判定，说明每个具体程序都无法判断自己是否会停止\nB. 该问题只是暂时没人写出算法，等算力提升后就能解决\nC. 该问题不存在通用算法，但许多具体程序的运行时间仍可分析\nD. 用启发式方法可以在有限步内对所有输入给出正确判断", back: "答案：C\n简析：一句话解析：A 把「通用算法不可判定」扩大成「每个具体程序都判断不了」，B 把不可判定误当成工程难题，D 把启发式方法误当成能保证正确判断的算法。\n\n正确选项：该问题不存在通用算法，但许多具体程序的运行时间仍可分析", source: "ai-mcq", verified: true },
  { id: "csp-scenario-020", deck: "csp-scenario", category: "AP CSP · 情境题", front: "快递公司要在 30 个城市之间找最短巡回路线，精确算法运行时间过长，公司改用「最近邻 + 局部调整」的方法。哪项正确？\nA. 只要运行足够久，这种方法最终一定能给出最优路线\nB. 这种方法能较快得到较好的路线，但不保证是最优解\nC. 精确算法太慢，说明最短巡回路线问题没有任何算法可解\nD. 最近邻属于精确算法，因此得到的结果一定是最优结果", back: "答案：B\n简析：一句话解析：A 误以为启发式方法只要多运行就能收敛到最优，C 把计算代价高误当成不可解，D 把最近邻这种贪心策略误当成精确算法。\n\n正确选项：这种方法能较快得到较好的路线，但不保证是最优解", source: "ai-mcq", verified: true },
  { id: "csp-scenario-021", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生做「校园失物招领」程序：用户提交物品描述与照片，程序在 300 条记录的列表中按关键字匹配并显示可能的联系方式。在 Create task 报告中写 program purpose 与 input 时，哪项最合适？\nA. 说明程序使用了列表与过程，因此目的是展示数据类型\nB. 只写「这个程序很有用，能帮助很多人」就足够，不必写输入\nC. 说明程序的目的是运行时不出错，输入为 CPU 与内存使用情况\nD. 说明目的是帮失物与失主匹配，输入是用户填写的描述与照片", back: "答案：D\n简析：一句话解析：A 把实现细节当成目的，B 只有泛泛的夸奖且缺少输入说明，C 把「不报错」当目的并写错了输入来源。\n\n正确选项：说明目的是帮失物与失主匹配，输入是用户填写的描述与照片", source: "ai-mcq", verified: true },
  { id: "csp-scenario-022", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生写了过程 FIND(items, key)，返回 key 第一次出现的下标，找不到时返回 -1，并在程序中多处调用。在 Create task 报告中描述该过程时，哪项最合适？\nA. 说明参数与返回值的含义，并说明它在程序中如何被调用\nB. 说明该过程属于抽象，因此报告中不必写出参数与返回值的含义\nC. 逐行说明过程内部每条语句的语法，以便读者照着抄写\nD. 说明该过程用了循环，因此属于数据抽象而不是过程抽象", back: "答案：A\n简析：一句话解析：B 把抽象误解为可以省略接口说明，C 把报告写成逐行语法讲解，D 混淆了过程抽象与数据抽象。\n\n正确选项：说明参数与返回值的含义，并说明它在程序中如何被调用", source: "ai-mcq", verified: true },
  { id: "csp-scenario-023", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生的程序通过了案例 1、2、3 的测试，但输入空列表时会崩溃。按 Create task 对测试的要求，哪项最合适？\nA. 只要三个案例都通过，就能在报告中说明程序已经正确\nB. 记录每个案例的输入与预期结果，补充空列表情形并修改代码\nC. 崩溃说明这只是语法错误，应从报告中删掉该案例以免影响评分\nD. 只要把程序整体重写一遍，就不必记录之前用过的测试数据", back: "答案：B\n简析：一句话解析：A 把通过三个用例等同于程序正确，C 误判为空列表崩溃属于语法错误并想隐藏用例，D 以为重写代码后测试记录可以省略。\n\n正确选项：记录每个案例的输入与预期结果，补充空列表情形并修改代码", source: "ai-mcq", verified: true },
  { id: "csp-scenario-024", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生的程序使用了网上下载的背景音乐、同学的一张照片，以及从公开网站抓取的 200 条用户评论。哪项最合适？\nA. 网上公开的内容都属于公有领域，因此可以直接使用且无需注明来源\nB. 只要在报告中写出音乐的名称，就不必考虑授权与个人数据\nC. 使用有许可的素材并注明来源，同时保护评论中的个人信息\nD. 抓取公开评论属于使用公开数据，因此不存在任何隐私问题", back: "答案：C\n简析：一句话解析：A 把公开可见误当成公有领域，B 只做署名却忽略授权与个人信息，D 误以为公开数据不存在隐私问题。\n\n正确选项：使用有许可的素材并注明来源，同时保护评论中的个人信息", source: "ai-mcq", verified: true },
  { id: "csp-scenario-025", deck: "csp-scenario", category: "AP CSP · 情境题", front: "学生把「统计每名学生本周总步数」写成过程 TOTAL(steps, days)，并在主程序中多处调用。关于抽象与报告内容，哪项正确？\nA. 过程属于抽象，因此报告中不必说明程序面向的用户是谁\nB. 因为过程会被多次调用，所以它属于模拟而不是一种抽象方法\nC. 过程内部的变量名必须与调用处一致，否则参数传递会失效\nD. 带参数的过程属于抽象，报告中仍需说明面向的用户与用途", back: "答案：D\n简析：一句话解析：A 以为用了抽象就不必写用户说明，B 把过程抽象误当成模拟，C 编造了参数传递对变量名的要求。\n\n正确选项：带参数的过程属于抽象，报告中仍需说明面向的用户与用途", source: "ai-mcq", verified: true },
];
